READ_ROWS = 2598
READ_CLUT_ROWS = 3417

#: the containers the census rendered, as id ranges -- a covered container that reads no page's bytes
#: has no rows, and is still covered: its pages have no channel-D evidence, which is a measurement.
_COVERED_RANGES: Tuple[Tuple[int, int], ...] = (
    (0, 15), (17, 17), (21, 36), (38, 38), (40, 79), (81, 83), (85, 90), (92, 99),
    (120, 199), (201, 262), (265, 272), (274, 312), (377, 378), (381, 392), (394, 425), (427, 429),
    (431, 441), (443, 443), (445, 447), (457, 460), (486, 487), (489, 510),
)
COVERED = frozenset(i for a, b in _COVERED_RANGES for i in range(a, b + 1))

#: what the census measures and what it cannot see -- quoted wherever it speaks.
CAVEAT = (
    "the draw census is a DRAW, not a binding: every fragment the headless plugin's draws sampled of "
    "these bytes, on the screen and into the render target, on the live cast path (Battle Speed < 3), "
    "under the headless stage's camera and targets -- a draw on a frame the stage never reached, or "
    "one a real battle's camera and targets would change, is invisible to it")


@dataclass(frozen=True)
class Read:
    """One page's bytes, read at one cell and one depth, by the draws of one container."""
    #: the container offset of the page whose bytes were read
    page: int
    #: the VRAM cell the draw read them at
    cell: Tuple[int, int]
    bpp: int
    #: fragments that sampled the bytes on the SCREEN, before the cutout test
    screen: int
    #: ... of them, the ones that changed a screen pixel (the bytes reaching the screen as they stand)
    shown: int
    screen_frames: int
    #: fragments that sampled the bytes into the DR_AREA render target
    target: int
    target_frames: int
    #: the CLUT cells these reads went through, LOWEST ADDRESS FIRST (the class-C display rule)
    cluts: Tuple[Tuple[Tuple[int, int], int], ...] = ()

    def describe(self) -> str:
        parts = []
        if self.screen:
            parts.append("%d fragment(s) on the screen over %d frame(s), %d of them changing a pixel"
                         % (self.screen, self.screen_frames, self.shown))
        if self.target:
            parts.append("%d into the render target over %d frame(s)" % (self.target, self.target_frames))
        via = ", ".join("CLUT x%d_y%d" % c for c, _n in self.cluts)
        return "%dbpp at x%d_y%d (%s%s)" % (self.bpp, self.cell[0], self.cell[1], "; ".join(parts),
                                            (", through " + via) if via else "")


def _reads() -> Dict[int, Tuple[Read, ...]]:
    split: Dict[Tuple[int, ...], list] = {}
    for ef, pg, x, y, bpp, cx, cy, n in _READ_CLUT_ROWS:
        split.setdefault((ef, pg, x, y, bpp), []).append(((cx, cy), n))
    out: Dict[int, list] = {}
    for ef, pg, x, y, bpp, sr, sh, sf, tr, tf in _READ_ROWS:
        out.setdefault(ef, []).append(Read(
            page=pg, cell=(x, y), bpp=bpp, screen=sr, shown=sh, screen_frames=sf, target=tr,
            target_frames=tf,
            cluts=tuple(sorted(split.get((ef, pg, x, y, bpp), ()), key=lambda c: (c[0][1], c[0][0])))))
    return {ef: tuple(v) for ef, v in out.items()}


#: ``{effect: (Read, ...)}`` -- in table order (page, cell, depth).
READS: Dict[int, Tuple[Read, ...]] = _reads()


def censused(effect: Optional[int]) -> bool:
    """Whether the table speaks for this container at all (a covered container may read no page)."""
    return effect is not None and (int(effect) in COVERED or int(effect) in READS)


def reads(effect: Optional[int], page: Optional[int] = None,
          cell: Optional[Tuple[int, int]] = None) -> Tuple[Read, ...]:
    """The reads of one container's draws: of ``page``'s bytes (wherever they were read), or -- with
    ``cell`` and no ``page`` -- at one cell (whatever page's bytes).  Shallowest depth first."""
    if effect is None:
        return ()
    rs = READS.get(int(effect), ())
    if page is not None:
        rs = tuple(r for r in rs if r.page == int(page))
    if cell is not None:
        c = (int(cell[0]), int(cell[1]))
        rs = tuple(r for r in rs if r.cell == c)
    return tuple(sorted(rs, key=lambda r: (r.bpp, r.cell[1], r.cell[0])))


assert len(_READ_ROWS) == READ_ROWS
assert len(COVERED) in (0, CENSUS_CONTAINERS) and set(READS) <= COVERED | set(READS)
assert len(_READ_CLUT_ROWS) == READ_CLUT_ROWS
assert {r[4] for r in _READ_ROWS} <= {4, 8, 15}
assert all(r[1] >= 0 and r[5] >= r[6] and (r[5] or r[8]) for r in _READ_ROWS)
assert {r[:5] for r in _READ_CLUT_ROWS} <= {r[:5] for r in _READ_ROWS}


def _split_sums() -> Dict[Tuple[int, ...], int]:
    s: Dict[Tuple[int, ...], int] = {}
    for c in _READ_CLUT_ROWS:
        s[c[:5]] = s.get(c[:5], 0) + c[7]
    return s


#: every indexed row's CLUT split sums to its reads, screen and target together
_SUMS = _split_sums()
assert all(_SUMS.get(r[:5], 0) == r[5] + r[8] for r in _READ_ROWS if r[4] != 15)
del _SUMS
